func traversableTempDir(t *testing.T) string {
	t.Helper()
	dir, err := os.MkdirTemp("/tmp", "ts-terrabase-root-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	if err := os.Chmod(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

func validateTerraBaseRoot(root, installRoot, stateRoot string, identity WorkloadIdentity) error {
	return validateWorkloadRoot("terrabase", root, identity, installRoot, stateRoot)
}

func validateWorkloadRoot(name, root string, identity WorkloadIdentity, others ...string) error {
	separator := string(filepath.Separator)
	for _, other := range others {
		if other != "" && (root == other || strings.HasPrefix(root, other+separator) || strings.HasPrefix(other, root+separator)) {
			return errors.New(name + " root must be separate from the install, state and other workload roots")
		}
	}
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == separator {
		return errors.New(name + " root must be a clean absolute path other than /")
	}
	// Only the workload root may be absent; every parent must already be safe.
	if err := inspectWorkloadPath(filepath.Dir(root), identity, true, false, false); err != nil {
		return fmt.Errorf("%s root parent: %w", name, err)
	}
	// Every existing component is a real, non-replaceable directory...
	if err := inspectWorkloadPath(root, identity, true, true, false); err != nil {
		return fmt.Errorf("%s root: %w", name, err)
	}
	// ...and the workload cannot create the root before the agent does, not
	// even in a sticky parent such as /tmp.
	if info, err := os.Lstat(filepath.Dir(root)); err == nil && identity.UID != uint32(os.Geteuid()) {
		owner, _ := info.Sys().(*syscall.Stat_t)
		write := info.Mode().Perm() & 0o002
		if owner != nil && owner.Gid == identity.GID {
			write = info.Mode().Perm() & 0o020
		}
		if owner != nil && owner.Uid == identity.UID {
			write = info.Mode().Perm() & 0o200
		}
		if write != 0 {
			return errors.New("the workload identity can create entries next to the " + name + " root")
		}
	}
	// ...so the path resolves to itself.
	existing := root
	for {
		if _, err := os.Lstat(existing); err == nil {
			break
		}
		existing = filepath.Dir(existing)
	}
	if resolved, err := filepath.EvalSymlinks(existing); err != nil || resolved != existing {
		return fmt.Errorf("%s root %s does not resolve to itself", name, existing)
	}
	return nil
}

func (a *Agent) prepareTerraBase(ctx context.Context, d Desired) (map[string]string, time.Time, error) {
	if len(d.Args) != 0 {
		// The binary lets an argument override the host-owned settings.
		return nil, time.Time{}, errors.New("terrabase members take no arguments")
	}
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return nil, time.Time{}, err
	}
	peer, listed := a.terraBasePeer(profile)
	if !listed {
		return nil, time.Time{}, fmt.Errorf("node %s is not in %s", a.cfg.Node, terrabase.EnvPeers)
	}
	// Recheck the ancestors right before the privileged effects below.
	if err := validateTerraBaseRoot(a.cfg.TerraBaseRoot, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.WorkloadIdentity); err != nil {
		return nil, time.Time{}, err
	}
	layout := terrabase.Layout(a.cfg.TerraBaseRoot)
	supervisor, uid, gid := os.Geteuid(), int(a.cfg.WorkloadIdentity.UID), int(a.cfg.WorkloadIdentity.GID)
	// The binary writes its databases and extracted libraries; it only
	// reads its TLS material, which stays supervisor-owned.
	type ownedDir struct {
		path     string
		uid, gid int
		mode     os.FileMode
	}
	dirs := []ownedDir{{string(layout), supervisor, gid, 0o750}, {layout.TLS(), supervisor, gid, 0o750},
		{layout.Bundle(), uid, gid, 0o700}}
	if !a.cfg.TerraBaseDataVolume {
		dirs = append(dirs, ownedDir{layout.Data(), uid, gid, 0o700})
	}
	for _, dir := range dirs {
		if err := ensureOwnedDir(dir.path, dir.uid, dir.gid, dir.mode); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The volume initializer owns a data volume mount; never fall back to
	// the boot disk without one.
	if a.cfg.TerraBaseDataVolume {
		// Artifact and controller requests may have outlasted the caller's
		// fence. Stop any remaining writer before repairing a lost mount.
		if _, err := a.fenceTerraBaseMember(ctx, d.Role); err != nil {
			return nil, time.Time{}, err
		}
		if err := a.ensureTerraBaseDataVolume(ctx); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The member's private key never reaches disk (TS-745).
	if a.cfg.MemoryRuntime {
		if err := vaultsecret.RequireMemoryFilesystem(layout.TLS()); err != nil {
			return nil, time.Time{}, err
		}
	}
	key, err := os.ReadFile(layout.Key())
	if errors.Is(err, os.ErrNotExist) {
		if key, _, err = terrabase.NewMemberKey(); err == nil {
			err = writeOwnedFile(layout.Key(), key, gid)
		}
	}
	if err != nil {
		return nil, time.Time{}, err
	}
	certificate, _ := os.ReadFile(layout.Certificate())
	ca, _ := os.ReadFile(layout.CA())
	if !terrabase.CurrentCertificate(certificate, key, ca, peer, time.Now()) {
		csr, err := terrabase.CertificateRequest(key)
		if err != nil {
			return nil, time.Time{}, err
		}
		var reply terraBasePeerReply
		if err := a.request(ctx, "terrabase-peer", terraBasePeerQuery{CSR: csr}, &reply); err != nil {
			return nil, time.Time{}, err
		}
		if !terrabase.CurrentCertificate(reply.Certificate, key, reply.CA, peer, time.Now()) {
			return nil, time.Time{}, errors.New("controller returned an unusable TerraBase member certificate")
		}
		if err := writeOwnedFile(layout.CA(), reply.CA, gid); err != nil {
			return nil, time.Time{}, err
		}
		if err := writeOwnedFile(layout.Certificate(), reply.Certificate, gid); err != nil {
			return nil, time.Time{}, err
		}
		certificate = reply.Certificate
	}
	return layout.Env(d.Env, profile, peer.Name), terrabase.CertificateExpiry(certificate), nil
}

func ensureOwnedDir(path string, uid, gid int, mode os.FileMode) error {
	if err := os.Mkdir(path, mode); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return fmt.Errorf("%s must be a directory, not a symlink: %w", path, err)
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if int(stat.Uid) == uid && int(stat.Gid) == gid && stat.Mode&0o7777 == uint32(mode.Perm()) {
		return nil
	}
	if err := unix.Fchown(fd, os.Geteuid(), gid); err != nil {
		return err
	}
	if err := unix.Fchmod(fd, uint32(mode.Perm())); err != nil {
		return err
	}
	return unix.Fchown(fd, uid, gid)
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

renewal.text:
func (r *stopRecorder) Stop(_ context.Context, role string) error {
	r.stopped = append(r.stopped, role)
	return r.err
}

func testTerraBaseMemberCertificateRenewal(t *testing.T, address string) {
	now := time.Now()
	caPEM, caKey, err := terrabase.NewCA("gru-1", now)
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	for name, data := range map[string][]byte{"ca.pem": caPEM, "ca.key": caKey} {
		if err := os.WriteFile(filepath.Join(dir, name), data, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	ca, err := terrabase.LoadCA(filepath.Join(dir, "ca.pem"), filepath.Join(dir, "ca.key"))
	if err != nil {
		t.Fatal(err)
	}
	// The member's peer listener: it serves whichever certificate served holds.
	roots := x509.NewCertPool()
	roots.AppendCertsFromPEM(caPEM)
	var served atomic.Pointer[tls.Certificate]
	listener, err := tls.Listen("tcp", "127.0.0.1:0", &tls.Config{ClientAuth: tls.RequireAndVerifyClientCert, ClientCAs: roots,
		GetCertificate: func(*tls.ClientHelloInfo) (*tls.Certificate, error) { return served.Load(), nil }})
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	go func() {
		for {
			connection, err := listener.Accept()
			if err != nil {
				return
			}
			_ = connection.(*tls.Conn).Handshake()
			_ = connection.Close()
		}
	}()
	port := listener.Addr().(*net.TCPAddr).Port
	peer := terrabase.Peer{Name: "gru-1-db-1", Address: netip.AddrPortFrom(netip.MustParseAddr(address), uint16(port))}
	key, csr, err := terrabase.NewMemberKey()
	if err != nil {
		t.Fatal(err)
	}
	renewed, err := ca.Issue(csr, peer, now)
	if err != nil {
		t.Fatal(err)
	}
	expiring, err := ca.Issue(csr, peer, now.Add(-89*24*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	root := filepath.Join(dir, "terrabase")
	layout := terrabase.Layout(root)
	for _, path := range []string{root, layout.TLS()} {
		if err := os.Mkdir(path, 0o750); err != nil {
			t.Fatal(err)
		}
	}
	for path, data := range map[string][]byte{layout.Key(): key, layout.Certificate(): renewed, layout.CA(): ca.CertificatePEM()} {
		if err := os.WriteFile(path, data, 0o440); err != nil {
			t.Fatal(err)
		}
	}
	serve := func(certificate []byte) {
		pair, err := tls.X509KeyPair(certificate, key)
		if err != nil {
			t.Fatal(err)
		}
		served.Store(&pair)
	}
	runner := &stopRecorder{}
	agent := &Agent{runner: runner, terraBase: map[string]terraBaseMember{}, cfg: AgentConfig{Node: peer.Name,
		TerraBaseRoot: root, WorkloadIdentity: WorkloadIdentity{UID: uint32(os.Getuid()), GID: uint32(os.Getgid())}}}
	d := Desired{Role: terrabase.Role, Digest: "d", Env: map[string]string{terrabase.EnvAdminPort: "1",
		terrabase.EnvPeerPort: fmt.Sprint(port), terrabase.EnvPeers: "gru-1-db-1=" + peer.Address.String()}}
	loadedExpiry := terrabase.CertificateExpiry(expiring)

	serve(expiring)
	agent.terraBase[d.Role] = terraBaseMember{certificateExpiry: now.Add(80 * 24 * time.Hour)}
	if report := agent.terraBaseRunningReport(t.Context(), d); report.State != "starting" || len(runner.stopped) != 0 {
		t.Fatalf("certificate far from expiry: report %+v, stops %v", report, runner.stopped)
	}
	serve(renewed)
	agent.terraBase[d.Role] = terraBaseMember{certificateExpiry: loadedExpiry}
	if report := agent.terraBaseRunningReport(t.Context(), d); len(runner.stopped) != 0 ||
		!agent.terraBase[d.Role].certificateExpiry.Equal(terrabase.CertificateExpiry(renewed)) {
		t.Fatalf("member serving the reloaded certificate: report %+v, stops %v", report, runner.stopped)
	}
	serve(expiring)
	agent.terraBase[d.Role] = terraBaseMember{certificateExpiry: loadedExpiry}
	if report := agent.terraBaseRunningReport(t.Context(), d); report.State != "starting" || len(runner.stopped) != 1 {
		t.Fatalf("member still serving the expiring certificate: report %+v, stops %v", report, runner.stopped)
	}
	if _, kept := agent.terraBase[d.Role]; kept {
		t.Fatal("restarted member keeps its old certificate expiry")
	}
	listener.Close()
	runner.err = errors.New("cgroup busy")
	agent.terraBase[d.Role] = terraBaseMember{certificateExpiry: loadedExpiry}
	if agent.terraBaseRunningReport(t.Context(), d); len(runner.stopped) != 2 {
		t.Fatalf("unreachable member near certificate expiry was not restarted: stops %v", runner.stopped)
	}
	if !agent.terraBase[d.Role].certificateExpiry.Equal(loadedExpiry) {
		t.Fatal("a failed stop forgot the expiry, so the member would never be checked again")
	}
}

func (a *Agent) terraBaseRunningReport(ctx context.Context, d Desired) Report {
	// Publication rechecks the cached observation's freshness and exact process while this poll runs.
	// reconcile fenced a member whose data volume is gone before it got
	// here; these checks stop it when the volume goes between the two or
	// while preparation renews the certificate and maintains the mount.
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), err))
	}
	_, _, renewErr := a.prepareTerraBase(ctx, d)
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), renewErr, err))
	}
	// ponytail: a per-node offset of one to seven days keeps the members of
	// a cell that cannot reload from restarting together.
	restartBefore := time.Duration(24+crc32.ChecksumIEEE([]byte(a.cfg.Node))%144) * time.Hour
	member := a.terraBase[d.Role]
	if renewErr == nil && !member.certificateExpiry.IsZero() && time.Until(member.certificateExpiry) < restartBefore {
		served, err := a.terraBaseServedExpiry(ctx, d)
		if err != nil || time.Until(served) < restartBefore {
			stopErr := a.runner.Stop(ctx, d.Role)
			if stopErr == nil {
				delete(a.terraBase, d.Role)
			}
			return a.reportFor(d, "starting", errors.Join(errors.New("restarting to load the renewed member certificate"),
				err, stopErr))
		}
		member.certificateExpiry = served
		a.terraBase[d.Role] = member
	}
	state, healthErr := a.terraBaseState(ctx, d)
	if state == "running" {
		a.collectTerraBaseWAN(ctx, d)
	}
	return a.reportFor(d, state, errors.Join(healthErr, renewErr))
}

func (a *Agent) terraBaseServedExpiry(ctx context.Context, d Desired) (time.Time, error) {
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return time.Time{}, err
	}
	peer, _ := a.terraBasePeer(profile)
	layout := terrabase.Layout(a.cfg.TerraBaseRoot)
	ca, err := os.ReadFile(layout.CA())
	if err != nil {
		return time.Time{}, err
	}
	earliest := time.Time{}
	for _, port := range []int{profile.PeerPort, profile.ClientPort} {
		if port == 0 {
			continue
		}
		served, err := terrabase.ServedCertificateExpiry(ctx, port, peer, layout.Certificate(), layout.Key(), ca)
		if err != nil {
			return time.Time{}, err
		}
		if earliest.IsZero() || served.Before(earliest) {
			earliest = served
		}
	}
	return earliest, nil
}

func (a *Agent) terraBaseState(ctx context.Context, d Desired) (string, error) {
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return "", err
	}
	if err := terrabase.Healthy(ctx, profile.AdminPort); err != nil {
		return "starting", err
	}
	if profile.ClientPort != 0 {
		peer, _ := a.terraBasePeer(profile)
		layout := terrabase.Layout(a.cfg.TerraBaseRoot)
		ca, err := os.ReadFile(layout.CA())
		if err == nil {
			err = terrabase.Ready(ctx, profile.ClientPort, peer, layout.Certificate(), layout.Key(), ca)
		}
		if err != nil {
			return "starting", err
		}
	}
	return "running", nil
}

func ServedCertificateExpiry(ctx context.Context, port int, peer Peer, certificateFile, keyFile string, caPEM []byte) (time.Time, error) {
	config, err := memberTLS(peer, certificateFile, keyFile, caPEM)
	if err != nil {
		return time.Time{}, err
	}
	dialer := tls.Dialer{NetDialer: &net.Dialer{Timeout: 2 * time.Second}, Config: config}
	connection, err := dialer.DialContext(ctx, "tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return time.Time{}, err
	}
	defer connection.Close()
	return connection.(*tls.Conn).ConnectionState().PeerCertificates[0].NotAfter, nil
}

func memberTLS(peer Peer, certificateFile, keyFile string, caPEM []byte) (*tls.Config, error) {
	pair, err := tls.LoadX509KeyPair(certificateFile, keyFile)
	if err != nil {
		return nil, err
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(caPEM) {
		return nil, errors.New("member CA does not parse")
	}
	return &tls.Config{Certificates: []tls.Certificate{pair}, RootCAs: roots, ServerName: peer.Address.Addr().String(),
		NextProtos: []string{"h2", "http/1.1"}, MinVersion: tls.VersionTLS12}, nil
}

func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

