func (c *Controller) serveTerraBasePeer(ctx context.Context, req request, r Registration) (any, error) {
	if c.terraBaseCA == nil {
		return nil, errors.New("terrabase member CA is not configured")
	}
	var query terraBasePeerQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(r.Roles, terrabase.Role) || r.ManagedOCI != nil {
		return nil, errors.New("host does not run C# TerraBase members")
	}
	d, _, exists, err := c.readDesired(ctx, req.Node, terrabase.Role)
	if err != nil {
		return nil, err
	}
	if !exists || d.Withdrawn || d.ManagedMember != nil {
		return nil, errors.New("host has no active TerraBase member")
	}
	if err := validateDesired(d, c.cell, r); err != nil {
		return nil, err
	}
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return nil, err
	}
	var address string
	if c.nodeAddress != nil {
		address = c.nodeAddress(req.Node)
	}
	peer, listed := profile.Member(req.Node, address)
	if !listed {
		return nil, fmt.Errorf("node %s is not in %s", req.Node, terrabase.EnvPeers)
	}
	certificate, err := c.terraBaseCA.Issue(query.CSR, peer, time.Now())
	if err != nil {
		return nil, err
	}
	return terraBasePeerReply{Certificate: certificate, CA: c.terraBaseCA.CertificatePEM()}, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

func (m *memoryMutations) key(kind authority.HostMutationKind, subject string) string {
	return string(kind) + "." + subject
}

func (m *memoryMutations) ReadHostMutation(_ context.Context, kind authority.HostMutationKind, subject string) (authority.LogEntry, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	entry, ok := m.entries[m.key(kind, subject)]
	if !ok {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	return entry, nil
}

func (m *memoryMutations) CommitHostMutation(ctx context.Context, epoch uint64, kind authority.HostMutationKind, subject, operation string, expected uint64, payload []byte) (uint64, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	key := m.key(kind, subject)
	if m.entries[key].Sequence != expected {
		return 0, authority.ErrConflict
	}
	record, err := json.Marshal(struct {
		Version     int                        `json:"version"`
		Kind        authority.HostMutationKind `json:"kind"`
		Scope       string                     `json:"scope"`
		SubjectKey  string                     `json:"subject_key"`
		OperationID string                     `json:"operation_id"`
		Epoch       uint64                     `json:"epoch"`
		Payload     []byte                     `json:"payload"`
	}{1, kind, "gru", subject, operation, epoch, payload})
	if err != nil {
		return 0, err
	}
	ack, err := m.js.Publish(ctx, "ts.control.gru.host."+string(kind)+"."+subject, record)
	if err != nil {
		return 0, err
	}
	m.sequence = ack.Sequence
	m.entries[key] = authority.LogEntry{Kind: kind, SubjectKey: subject, OperationID: operation, Epoch: epoch, Sequence: m.sequence, Payload: append([]byte(nil), payload...)}
	return m.sequence, nil
}

func testController(t *testing.T) (*Controller, *nats.Conn, jetstream.ObjectStore, *memoryMutations, ed25519.PrivateKey) {
	return testControllerWithVerifier(t, nil)
}

func testControllerWithVerifier(t *testing.T, verifier ManagedRegistrationVerifier, options ...func(*ControllerConfig)) (*Controller, *nats.Conn, jetstream.ObjectStore, *memoryMutations, ed25519.PrivateKey) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	log, err := js.CreateStream(t.Context(), jetstream.StreamConfig{Name: "TS_CONTROL_LOG", Subjects: []string{"ts.control.gru.>"}, Storage: jetstream.FileStorage, Replicas: 1})
	if err != nil {
		t.Fatal(err)
	}
	store, err := js.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: "HOST_TEST_ARTIFACTS", Storage: jetstream.FileStorage})
	if err != nil {
		t.Fatal(err)
	}
	_, controllerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	mutations := &memoryMutations{entries: make(map[string]authority.LogEntry), js: js}
	config := ControllerConfig{
		Cell: "gru", Conn: conn, JS: js, ControlLog: log, Artifacts: store, ResponseKey: controllerKey,
		StateReplicas: 1, HostMutations: verifiedMemoryMutations{memoryMutations: mutations},
		ManagedRegistrationVerifier: verifier, ManagedDesiredVerifier: fixtureManagedDesiredVerifier,
		ManagedEffectGate: func(_ context.Context, epoch uint64, scope authority.WorkloadScope) (func(), error) {
			if epoch == 0 || scope.DatabaseID == "" || scope.PartitionID == "" {
				return nil, errors.New("test terminal effect gate requires a scoped placement")
			}
			return func() {}, nil
		},
		AuthorityEpoch: func() uint64 { return 1 }, AuthorityGuard: func(context.Context, uint64) error { return nil },
	}
	for _, option := range options {
		option(&config)
	}
	c, err := NewController(t.Context(), config)
	if err != nil {
		t.Fatal(err)
	}
	return c, conn, store, mutations, controllerKey
}

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) ApplyDesired(ctx context.Context, d Desired) (Receipt, error) {
	if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
		return Receipt{}, err
	}
	c.retireMu.RLock()
	defer c.retireMu.RUnlock()
	if !d.Withdrawn {
		retired, err := c.retired(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if retired {
			return Receipt{}, fmt.Errorf("%w: %s", ErrHostRetiring, d.Node)
		}
	}
	r, _, exists, err := c.readRegistration(ctx, d.Node)
	if err != nil {
		return Receipt{}, err
	}
	if !exists {
		return Receipt{}, errors.New("host is not registered")
	}
	if err := validateDesired(d, c.cell, r); err != nil {
		return Receipt{}, err
	}
	if d.ManagedMember != nil && !d.Withdrawn {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil || c.managedDesiredVerifier == nil {
			return Receipt{}, errors.New("managed desired requires a terminal effect gate, placement scope and durable verifier")
		}
		release, err := c.managedEffectGate(ctx, d.AuthorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	bucket := ""
	if !d.Withdrawn {
		info, err := c.artifacts.GetInfo(ctx, "sha256-"+d.Digest)
		if err != nil {
			return Receipt{}, err
		}
		if info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > maxArtifactBytes {
			return Receipt{}, errors.New("artifact is absent, linked or outside size limit")
		}
		bucket = info.Bucket
	}
	payload, operationID, err := mutationPayload(d)
	if err != nil {
		return Receipt{}, err
	}
	key := desiredSubjectKey(c.cell, d.Node, d.Role)
	for range 8 {
		currentRegistration, _, registered, err := c.readRegistration(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if !registered || validateDesired(d, c.cell, currentRegistration) != nil {
			return Receipt{}, errors.New("registration changed before desired commit")
		}
		current, revision, exists, err := c.readDesired(ctx, d.Node, d.Role)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedMember == nil) != (d.ManagedMember == nil) {
				return Receipt{}, fmt.Errorf("%w: managed desired kind changed", ErrDesiredConflict)
			}
			if current.ManagedMember != nil && d.ManagedMember != nil &&
				(current.ManagedMember.Member != d.ManagedMember.Member || current.ManagedMember.OCI != d.ManagedMember.OCI ||
					current.ManagedMember.VolumeID != d.ManagedMember.VolumeID || current.ManagedMember.AttachmentID != d.ManagedMember.AttachmentID) {
				return Receipt{}, fmt.Errorf("%w: managed member or attachment retargeted", ErrDesiredConflict)
			}
			if d.AuthorityEpoch < current.AuthorityEpoch || d.Generation < current.Generation {
				return Receipt{}, fmt.Errorf("%w: generation or epoch moved backward", ErrDesiredConflict)
			}
			if d.Generation == current.Generation {
				if !sameDesiredTarget(d, current) {
					return Receipt{}, fmt.Errorf("%w: target changed within a generation", ErrDesiredConflict)
				}
				if d.AuthorityEpoch == current.AuthorityEpoch {
					return Receipt{d.Generation, revision}, nil
				}
			}
		}
		// The artifact collector deletes only metadata nobody touched since
		// it chose the artifact, so it cannot delete the bytes this desired
		// is about to name.
		if bucket != "" && c.conn != nil {
			js, err := c.conn.JetStream()
			if err != nil {
				return Receipt{}, err
			}
			if err := artifact.Touch(ctx, js, bucket, "sha256-"+d.Digest); err != nil {
				return Receipt{}, fmt.Errorf("pin desired artifact: %w", err)
			}
		}
		if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
			return Receipt{}, err
		}
		var written uint64
		if d.ManagedMember != nil && !d.Withdrawn {
			verified, ok := c.mutations.(authority.VerifiedHostMutationStore)
			if !ok {
				return Receipt{}, errors.New("managed desired mutation store lacks a final verifier fence")
			}
			verify := func(verifyCtx context.Context) error {
				return c.managedDesiredVerifier(verifyCtx, d, currentRegistration, current, exists)
			}
			written, err = verified.CommitHostMutationVerified(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload, verify)
		} else {
			written, err = c.mutations.CommitHostMutation(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload)
		}
		if err == nil {
			return Receipt{d.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("desired contention")
}

func LoadCA(certificateFile, keyFile string) (*CA, error) {
	certificatePEM, err := os.ReadFile(certificateFile)
	if err != nil {
		return nil, err
	}
	keyPEM, err := readOwnerOnly(keyFile)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA key: %w", err)
	}
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA: %w", err)
	}
	certificate := pair.Leaf
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if len(pair.Certificate) != 1 || !ok || !certificate.IsCA || certificate.KeyUsage&x509.KeyUsageCertSign == 0 {
		return nil, errors.New("terrabase member CA must be one CA certificate and its key")
	}
	return &CA{certificate: certificate, pem: certificatePEM, key: signer}, nil
}

func (ca *CA) Issue(csrDER []byte, peer Peer, now time.Time) ([]byte, error) {
	request, err := x509.ParseCertificateRequest(csrDER)
	if err != nil || request.CheckSignature() != nil {
		return nil, errors.New("invalid member certificate request")
	}
	if key, ok := request.PublicKey.(*ecdsa.PublicKey); !ok || key.Curve != elliptic.P256() {
		return nil, errors.New("member certificate request must use an ECDSA P-256 key")
	}
	notAfter := now.Add(memberValidity)
	if ca.certificate.NotAfter.Before(notAfter) {
		notAfter = ca.certificate.NotAfter
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: peer.Name},
		DNSNames: []string{peer.Name}, IPAddresses: []net.IP{peer.Address.Addr().AsSlice()},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: notAfter,
		KeyUsage:    x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, template, ca.certificate, request.PublicKey, ca.key)
	if err != nil {
		return nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), nil
}

func CurrentCertificate(certificatePEM, keyPEM, caPEM []byte, peer Peer, now time.Time) bool {
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil || len(pair.Certificate) != 1 {
		return false
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(caPEM) {
		return false
	}
	leaf := pair.Leaf
	_, err = leaf.Verify(x509.VerifyOptions{Roots: roots, CurrentTime: now,
		KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}})
	return err == nil && now.Add(renewBefore).Before(leaf.NotAfter) && leaf.Subject.CommonName == peer.Name &&
		len(leaf.IPAddresses) == 1 && leaf.IPAddresses[0].Equal(peer.Address.Addr().AsSlice())
}

