func (a *Agent) terraBaseState(ctx context.Context, d Desired) (string, error) {
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return "", err
	}
	if err := terrabase.Healthy(ctx, profile.AdminPort); err != nil {
		return "starting", err
	}
	if profile.ClientPort != 0 {
		peer, _ := a.terraBasePeer(profile)
		layout := terrabase.Layout(a.cfg.TerraBaseRoot)
		ca, err := os.ReadFile(layout.CA())
		if err == nil {
			err = terrabase.Ready(ctx, profile.ClientPort, peer, layout.Certificate(), layout.Key(), ca)
		}
		if err != nil {
			return "starting", err
		}
	}
	return "running", nil
}

func Ready(ctx context.Context, clientPort int, peer Peer, certificateFile, keyFile string, caPEM []byte) error {
	config, err := memberTLS(peer, certificateFile, keyFile, caPEM)
	if err != nil {
		return fmt.Errorf("terrabase readiness: %w", err)
	}
	// A plain transport speaks HTTP/1.1 only; offering h2 would let the
	// member pick a protocol it cannot read.
	config.NextProtos = []string{"http/1.1"}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://"+net.JoinHostPort("127.0.0.1", strconv.Itoa(clientPort))+"/readyz", nil)
	if err != nil {
		return err
	}
	client := &http.Client{Transport: &http.Transport{TLSClientConfig: config, DisableKeepAlives: true}}
	response, err := client.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase readiness: %w", err)
	}
	defer response.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(response.Body, 4096))
	if response.StatusCode != http.StatusOK {
		return fmt.Errorf("terrabase readiness: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

func memberTLS(peer Peer, certificateFile, keyFile string, caPEM []byte) (*tls.Config, error) {
	pair, err := tls.LoadX509KeyPair(certificateFile, keyFile)
	if err != nil {
		return nil, err
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(caPEM) {
		return nil, errors.New("member CA does not parse")
	}
	return &tls.Config{Certificates: []tls.Certificate{pair}, RootCAs: roots, ServerName: peer.Address.Addr().String(),
		NextProtos: []string{"h2", "http/1.1"}, MinVersion: tls.VersionTLS12}, nil
}

