func askTerraBaseFormatTest(t *testing.T, c *Controller, r Registration, query terraBaseFormatQuery) (terraBaseFormatReply, error) {
	t.Helper()
	wire, err := protocol.EncodeJSON(query)
	if err != nil {
		t.Fatal(err)
	}
	reply, err := c.serveTerraBaseFormat(t.Context(), request{Node: r.Node, Payload: wire}, r)
	if err != nil {
		return terraBaseFormatReply{}, err
	}
	return reply.(terraBaseFormatReply), nil
}

func signTerraBaseFormatTest(t *testing.T, cfg VolumeInitConfig, key ed25519.PrivateKey, reply terraBaseFormatReply, issued time.Time) protocol.Envelope {
	t.Helper()
	payload, err := protocol.EncodeJSON(reply)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := protocol.EncodeJSON(response{Nonce: "000000000000ab603a0258fc8d8a26df", Node: cfg.Node, SessionID: "00000000007WXF3V7BQMA11AT1", Epoch: 1,
		Operation: "terrabase-format", Payload: payload})
	if err != nil {
		t.Fatal(err)
	}
	signed, err := protocol.SignEnvelope(wire, protocol.EnvelopeScope{Region: cfg.Cell, Kind: "host.response.terrabase-format",
		Actor: "controller", OperationID: entityid.Derive("host-request", "000000000000ab603a0258fc8d8a26df"), Epoch: 1}, issued, issued.Add(requestTTL), key)
	if err != nil {
		t.Fatal(err)
	}
	return signed
}

func terraBaseFormatMarkerPath(cfg VolumeInitConfig) string {
	return filepath.Join(cfg.StateRoot, fmt.Sprintf("%s-%x", terraBaseFormatMarker, sha256.Sum256([]byte(cfg.TerraBaseDataVolumeID))))
}

func pendingTerraBaseFormatAttempt(cfg VolumeInitConfig) (string, error) {
	if attempt, err := readTerraBaseFormatAttempt(cfg); !errors.Is(err, os.ErrNotExist) {
		return attempt, err
	}
	if err := os.MkdirAll(cfg.StateRoot, 0o700); err != nil {
		return "", err
	}
	attempt, err := randomID()
	if err != nil {
		return "", err
	}
	if err := createDurableMarker(terraBaseFormatMarkerPath(cfg)+"-attempt", []byte(attempt+"\n")); err != nil && !errors.Is(err, os.ErrExist) {
		return "", err
	}
	return readTerraBaseFormatAttempt(cfg)
}

func readTerraBaseFormatAttempt(cfg VolumeInitConfig) (string, error) {
	if cfg.StateRoot == "" || !strings.HasPrefix(cfg.TerraBaseDataVolumeID, "ocid1.volume.") {
		return "", errors.New("first-format attempt needs its fixed state root and volume OCID")
	}
	path := terraBaseFormatMarkerPath(cfg) + "-attempt"
	file, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() != 27 {
		return "", errors.Join(errors.New("invalid durable first-format attempt"), err)
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || owner.Uid != uint32(os.Geteuid()) {
		return "", errors.New("first-format attempt is not owned by the initializer")
	}
	var wire [27]byte
	if _, err := io.ReadFull(file, wire[:]); err != nil {
		return "", err
	}
	attempt := string(wire[:26])
	if !entityid.Valid(attempt) || wire[26] != '\n' {
		return "", errors.New("invalid durable first-format attempt")
	}
	// A prior create may have failed during fsync. Re-establish durability
	// before returning even an existing attempt to the agent.
	if err := file.Sync(); err != nil {
		return "", err
	}
	directory, err := os.Open(filepath.Dir(path))
	if err != nil {
		return "", err
	}
	defer directory.Close()
	return attempt, directory.Sync()
}

func verifyTerraBaseFormatGrant(cfg VolumeInitConfig, signed protocol.Envelope) (string, error) {
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{
		Region: cfg.Cell, Kind: "host.response.terrabase-format", Actor: "controller",
		OperationID: signed.OperationID, Epoch: signed.Epoch,
	}, cfg.ControllerPublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return "", err
	}
	var reply response
	if err := decodeStrict([]byte(signed.Payload), &reply); err != nil {
		return "", err
	}
	if reply.Error != "" || !lowerHex(reply.Nonce, 32) || entityid.Derive("host-request", reply.Nonce) != signed.OperationID || reply.Epoch != signed.Epoch ||
		reply.Operation != "terrabase-format" || reply.Node != cfg.Node {
		return "", errors.New("first-format grant binding is invalid")
	}
	var grant terraBaseFormatReply
	if err := decodeStrict(reply.Payload, &grant); err != nil {
		return "", err
	}
	if !strings.HasPrefix(cfg.TerraBaseDataVolumeID, "ocid1.volume.") || grant.VolumeID != cfg.TerraBaseDataVolumeID {
		return "", errors.New("first-format grant belongs to another volume")
	}
	if !grant.Granted {
		return "", fmt.Errorf("member %s has no unused first-format authority for this initializer (ext4 %s); recover its original initializer state or restore the volume from a backup", cfg.Node, grant.UUID)
	}
	if !hostvolume.ValidUUID(grant.UUID) {
		return "", errors.New("first-format grant has no valid filesystem UUID")
	}
	attempt, err := readTerraBaseFormatAttempt(cfg)
	if err != nil {
		return "", fmt.Errorf("read the original initializer attempt: %w", err)
	}
	if grant.AttemptID != attempt {
		return "", errors.New("first-format grant belongs to another initializer attempt")
	}
	return grant.UUID, nil
}

func createDurableMarker(path string, content []byte) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	if _, err := file.Write(content); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	directory, err := os.Open(filepath.Dir(path))
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

