	}
	owner := info.Sys().(*syscall.Stat_t)
	if owner.Uid != id || owner.Gid != id || info.Mode().Perm() != mode {
		t.Fatalf("%s is %d:%d %v, want %d:%d %v", dir, owner.Uid, owner.Gid, info.Mode().Perm(), id, id, mode)
	}
}

